from pathlib import Path

# 1) Histogram workspace header + remove empty hint row for non-distribution views.
p = Path('apps/web/src/pages/histogram-page.ts')
s = p.read_text()
s = s.replace('''  headerControl.innerHTML = `\n    <span>Analysis</span>\n    <select class="histogram-view-select" aria-label="Histogram analysis view">''', '''  headerControl.innerHTML = `\n    <select class="histogram-view-select" aria-label="Histogram analysis view">''')
s = s.replace('''    <div class="histogram-workspace-bar">\n      <div class="histogram-distribution-controls" hidden>\n        <label><span>Channel</span><select class="histogram-channel"></select></label>\n        <label><span>Bins</span><select class="histogram-bin-count"><option>10</option><option selected>20</option><option>30</option><option>40</option><option>60</option></select></label>\n      </div>\n      <div class="histogram-workspace-hint">MLV-style table generation · all available log channels · selected channels decode on demand</div>\n    </div>''', '''    <div class="histogram-workspace-bar" hidden>\n      <div class="histogram-distribution-controls" hidden>\n        <label><span>Channel</span><select class="histogram-channel"></select></label>\n        <label><span>Bins</span><select class="histogram-bin-count"><option>10</option><option selected>20</option><option>30</option><option>40</option><option>60</option></select></label>\n      </div>\n    </div>''')
s = s.replace('''    distributionControls.hidden = !distribution;\n    distributionStage.hidden = !distribution;''', '''    const workspaceBar = page.querySelector<HTMLElement>('.histogram-workspace-bar');\n    if (workspaceBar) workspaceBar.hidden = !distribution;\n    distributionControls.hidden = !distribution;\n    distributionStage.hidden = !distribution;''')
p.write_text(s)

# 2) Table generator defaults, size/grid control, clearer presets, compact filter manager shell.
p = Path('apps/web/src/pages/histogram-table-generator-view.ts')
s = p.read_text()
s = s.replace("let currentAggregation: HistogramTableAggregation = 'mean';", "let currentAggregation: HistogramTableAggregation = 'weighted-mean';")
s = s.replace('''        <option value="mean" selected>Mean</option>\n        <option value="weighted-mean">MLV weighted mean</option>''', '''        <option value="weighted-mean" selected>MLV weighted mean</option>\n        <option value="mean">Mean</option>''')
s = s.replace('''        <summary>Presets</summary>\n        <div class="histogram-table-preset-popover">\n          <select class="histogram-preset-select" aria-label="Saved table preset"></select>\n          <div><button type="button" class="histogram-preset-apply">Apply</button><button type="button" class="histogram-preset-save">Save current…</button><button type="button" class="histogram-preset-delete">Delete</button></div>\n          <small>Presets retain channels, formulas by ID, filters, statistic, scope and axis configuration.</small>''', '''        <summary title="Saved Table Generator setups">Presets</summary>\n        <div class="histogram-table-preset-popover">\n          <select class="histogram-preset-select" aria-label="Saved table setup"></select>\n          <div><button type="button" class="histogram-preset-apply">Apply</button><button type="button" class="histogram-preset-save">Save setup…</button><button type="button" class="histogram-preset-delete">Delete</button></div>\n          <small>Saved setups retain scope, X/Y/Z, statistic, filters, axis/grid configuration and weighting options.</small>''')
s = s.replace('''      <details class="histogram-table-filters">\n        <summary>Filters <span class="histogram-filter-count">0</span></summary>\n        <div class="histogram-table-filter-popover">\n          <div class="histogram-filter-set-bar"><select class="histogram-filter-set-select" aria-label="Saved filter set"></select><button type="button" class="histogram-filter-set-apply">Apply</button><button type="button" class="histogram-filter-set-save">Save set…</button><button type="button" class="histogram-filter-set-delete">Delete</button></div>\n          <div class="histogram-filter-logic-bar"><label><span>Within group</span><select class="histogram-filter-within-logic"><option value="and">ALL</option><option value="or">ANY</option></select></label><label><span>Between groups</span><select class="histogram-filter-between-logic"><option value="and">ALL</option><option value="or">ANY</option></select></label><small>Assign rows to A/B/C. ALL/ANY controls conditions inside and between groups.</small></div>\n          <div class="histogram-filter-list"></div>\n          <div class="histogram-filter-actions">\n            <button type="button" class="histogram-add-filter">+ Add filter</button>\n            <span>Filters can use physical or calculated channels.</span>\n          </div>\n        </div>\n      </details>''', '''      <details class="histogram-table-filters">\n        <summary>Filters <span class="histogram-filter-count">0</span></summary>\n        <div class="histogram-table-filter-popover histogram-filter-manager">\n          <aside class="histogram-filter-library">\n            <header><strong>Saved filters</strong><button type="button" class="histogram-filter-set-save">Save current…</button></header>\n            <select class="histogram-filter-set-select" aria-label="Saved filter set" size="7"></select>\n            <footer><button type="button" class="histogram-filter-set-apply">Apply</button><button type="button" class="histogram-filter-set-delete">Delete</button></footer>\n          </aside>\n          <section class="histogram-filter-editor">\n            <header><div><strong>Filter conditions</strong><small>Qualify samples before they enter the table.</small></div><button type="button" class="histogram-add-filter">+ Condition</button></header>\n            <div class="histogram-filter-logic-bar"><label><span>Within group</span><select class="histogram-filter-within-logic"><option value="and">ALL</option><option value="or">ANY</option></select></label><label><span>Between groups</span><select class="histogram-filter-between-logic"><option value="and">ALL</option><option value="or">ANY</option></select></label><small>Rows may be grouped A/B/C. ALL/ANY controls conditions inside and between groups.</small></div>\n            <div class="histogram-filter-list"></div>\n            <footer class="histogram-filter-actions"><span>Physical and Math/Calculated channels are available.</span></footer>\n          </section>\n        </div>\n      </details>\n      <details class="histogram-table-size">\n        <summary title="Choose the visible auto-bin table grid">Size</summary>\n        <div class="histogram-table-size-popover">\n          <strong>Table grid</strong>\n          <div class="histogram-table-size-grid" role="group" aria-label="Table grid size">\n            <button type="button" data-grid="8x8">8×8</button>\n            <button type="button" data-grid="12x12">12×12</button>\n            <button type="button" data-grid="16x16">16×16</button>\n            <button type="button" data-grid="8x16">8×16</button>\n            <button type="button" data-grid="16x8">16×8</button>\n            <button type="button" data-grid="1x16">16×1</button>\n          </div>\n          <small>Grid size applies to Auto bins. Custom breakpoints and loaded MSQ tables keep their own dimensions.</small>\n        </div>\n      </details>''')
s = s.replace('Experimental MLV-style weighting:', 'MLV-style weighting:')
s = s.replace("  const axisSourceSelect = root.querySelector<HTMLSelectElement>('.histogram-table-axis-source');", "  const sizeButtons = [...root.querySelectorAll<HTMLButtonElement>('.histogram-table-size-grid [data-grid]')];\n  const axisSourceSelect = root.querySelector<HTMLSelectElement>('.histogram-table-axis-source');")
s = s.replace('''  addFilterButton.addEventListener('click', () => addFilter());\n  scopeSelect.addEventListener('change', () => scheduleRender());''', '''  addFilterButton.addEventListener('click', () => addFilter());\n  for (const button of sizeButtons) {\n    button.addEventListener('click', () => {\n      const raw = button.dataset.grid ?? '';\n      const [columnsRaw, rowsRaw] = raw.split('x');\n      const columns = Number(columnsRaw);\n      const rows = Number(rowsRaw);\n      if (!Number.isFinite(columns) || !Number.isFinite(rows)) return;\n      axisSourceSelect.value = 'auto';\n      xBinsInput.value = String(columns);\n      yBinsInput.value = String(rows);\n      axisSourceSelect.dispatchEvent(new Event('change'));\n      scheduleRender();\n    });\n  }\n  scopeSelect.addEventListener('change', () => scheduleRender());''')
p.write_text(s)

# 3) Workspace CSS: remove now-unused Analysis label spacing; hidden workspace bar must truly disappear.
p = Path('apps/web/src/styles/histogram-workspace.css')
s = p.read_text()
s = s.replace('''.histogram-workspace-bar {\n  flex: 0 0 36px;''', '''.histogram-workspace-bar {\n  flex: 0 0 36px;''')
if '.histogram-workspace-bar[hidden]' not in s:
    s = s.replace('''}\n\n.histogram-workspace-bar label,''', '''}\n\n.histogram-workspace-bar[hidden] {\n  display: none;\n}\n\n.histogram-workspace-bar label,''', 1)
s = s.replace('''.histogram-header-view > span {\n  color: #8298a6;\n  font-size:10px;\n  font-weight: 800;\n  letter-spacing: .04em;\n  text-transform: uppercase;\n}\n''', '')
p.write_text(s)

# 4) Table Generator CSS: compact filter manager + size popover.
p = Path('apps/web/src/styles/histogram-table-generator.css')
s = p.read_text()
s += '''\n\n/* Compact Table Generator filter manager and explicit grid-size control. */\n.histogram-table-size { position: relative; }\n.histogram-table-size-popover {\n  position: absolute; z-index: 30; top: 31px; right: 0; width: 250px; padding: 9px;\n  border: 1px solid #355164; border-radius: 4px; background: #0b171f;\n  box-shadow: 0 10px 30px rgba(0,0,0,.38);\n}\n.histogram-table-size-popover > strong { display:block; margin-bottom:7px; color:#e2edf2; font-size:10px; }\n.histogram-table-size-grid { display:grid; grid-template-columns:repeat(3,1fr); gap:5px; }\n.histogram-table-size-grid button { min-height:29px; border:1px solid #2b4554; background:#0f1d27; color:#dce9ef; border-radius:3px; font-size:10px; font-weight:700; }\n.histogram-table-size-grid button:hover { background:#173047; border-color:#3c6178; }\n.histogram-table-size-popover small { display:block; margin-top:7px; color:#8298a6; font-size:9px; line-height:1.4; }\n.histogram-filter-manager {\n  width:min(700px, calc(100vw - 32px)) !important; padding:0 !important;\n  grid-template-columns:220px minmax(360px,1fr) !important; gap:0 !important; overflow:hidden;\n}\n.histogram-filter-library { min-width:0; border-right:1px solid #243846; background:#09141c; display:grid; grid-template-rows:38px minmax(150px,1fr) 36px; }\n.histogram-filter-library header,.histogram-filter-editor > header { display:flex; align-items:center; gap:7px; padding:0 8px; border-bottom:1px solid #203341; background:#0d1922; }\n.histogram-filter-library header strong,.histogram-filter-editor > header strong { color:#e4edf2; font-size:10px; }\n.histogram-filter-library header button { margin-left:auto; min-height:25px; padding:0 7px; }\n.histogram-filter-library select { width:100%; min-height:150px; border:0 !important; border-radius:0 !important; background:#09141c !important; padding:4px !important; }\n.histogram-filter-library option { padding:5px 6px; }\n.histogram-filter-library footer { display:flex; gap:5px; align-items:center; padding:5px 7px; border-top:1px solid #203341; }\n.histogram-filter-editor { min-width:0; display:grid; grid-template-rows:38px auto minmax(120px,1fr) 30px; background:#0b171f; }\n.histogram-filter-editor > header > div { min-width:0; }\n.histogram-filter-editor > header small { display:block; color:#8197a5; font-size:9px; margin-top:1px; }\n.histogram-filter-editor > header button { margin-left:auto; min-height:26px; padding:0 8px; border-color:#2078cc; background:#1668be; font-weight:750; }\n.histogram-filter-manager .histogram-filter-logic-bar { margin:0; padding:6px 7px; border-bottom:1px solid #203341; }\n.histogram-filter-manager .histogram-filter-list { max-height:260px; overflow:auto; padding:5px 7px; }\n.histogram-filter-manager .histogram-filter-actions { min-height:30px; padding:0 8px; border-top:1px solid #203341; color:#8298a6; }\n'''
p.write_text(s)

# 5) Repository footnote: record the MLV comparison without making it an active pursuit.
p = Path('docs/DECISIONS.md')
s = p.read_text()
footnote = '''\n\n### Table Generator MLV weighted-mean parity note\n\nThe MLV-style weighted-mean implementation is considered sufficiently matched for current use. On the 2026-10-02_13.27.46.mlg comparison, representative cells matched MLV values and total hit weights effectively exactly; the large RPM 1800 / TPS 0 reference cell differed by only 19 contributing hits (EpicScope about 50,767 vs MLV 50,748, roughly 0.037%) while the weighted result remained 38.53 and total hit weight differed by about 0.97. This is retained as a compatibility footnote, not an active investigation. If revisited later, examine record-validity/retry handling before changing the established weighting geometry.\n'''
if '### Table Generator MLV weighted-mean parity note' not in s:
    s += footnote
p.write_text(s)
